var e=[{category:`外科`,items:[{id:`general-surgery`,name:`普外科`,intro:`以腹部外科、甲状腺、乳腺及软组织疾病为主，提供常规与微创手术治疗方案。`,scope:[`腹部外科（胃肠、肝胆胰脾）`,`甲状腺与乳腺外科`,`疝与腹壁外科`,`体表及软组织肿物`],conditions:[`腹痛原因待查`,`胆囊结石 / 胆囊炎`,`阑尾炎`,`腹股沟疝`,`甲状腺结节`,`乳腺肿块`]},{id:`orthopedics`,name:`骨科`,intro:`处理四肢、脊柱、关节、骨折及退变性疾病，保守与手术并重。`,scope:[`创伤骨科`,`关节外科`,`脊柱外科`,`运动损伤`,`小儿骨科`],conditions:[`颈肩腰腿痛`,`骨折 / 外伤`,`膝关节骨性关节炎`,`腰椎间盘突出`,`运动后扭伤`]},{id:`neurosurgery`,name:`神经外科`,intro:`针对颅脑、脊柱及外周神经的外科评估与干预。`,scope:[`颅脑外伤`,`脑血管病外科`,`脑肿瘤`,`脊髓脊柱外科`,`功能神经外科`],conditions:[`头部外伤`,`突发剧烈头痛`,`肢体无力 / 麻木`,`意识改变`]},{id:`cardiothoracic`,name:`心胸外科`,intro:`处理心脏、大血管及胸肺部外科疾病。`,scope:[`心脏外科`,`普胸外科`,`纵隔外科`],conditions:[`胸闷胸痛`,`肺部占位`,`纵隔肿物`,`心功能不全需外科评估`]},{id:`urology`,name:`泌尿外科`,intro:`肾、输尿管、膀胱、前列腺及男性生殖系统疾病诊疗。`,scope:[`泌尿系结石`,`前列腺疾病`,`泌尿系肿瘤`,`男科`],conditions:[`血尿`,`排尿困难`,`尿频尿急`,`结石相关腰痛`]},{id:`anorectal`,name:`肛肠外科`,intro:`专注于肛门直肠疾病的诊断与微创治疗。`,scope:[`痔`,`肛瘘`,`肛裂`,`直肠息肉`,`功能性便秘评估`],conditions:[`便血`,`肛门疼痛`,`肿物脱出`,`慢性便秘`]},{id:`burn-plastic`,name:`烧伤整形科`,intro:`急慢性烧烫伤、创面修复及整形相关疾病。`,scope:[`烧伤救治`,`慢性创面`,`瘢痕整形`,`软组织修复重建`],conditions:[`烧烫伤`,`长期不愈合伤口`,`明显瘢痕增生`,`皮肤软组织缺损`]}]},{category:`内科`,items:[{id:`respiratory`,name:`呼吸内科`,intro:`专注于气道、肺部及胸膜相关疾病的内科诊疗。`,scope:[`慢性气道疾病`,`肺部感染`,`间质性肺病`,`睡眠呼吸疾病`],conditions:[`慢性咳嗽`,`咳痰 / 喘息`,`胸闷气短`,`发热伴呼吸道症状`]},{id:`gastroenterology`,name:`消化内科`,intro:`负责食管、胃肠、肝胆胰等消化系统疾病诊治。`,scope:[`胃肠疾病`,`肝胆胰疾病`,`消化道内镜`,`营养与吸收`],conditions:[`腹痛`,`反酸 / 烧心`,`腹泻 / 便秘`,`消瘦 / 食欲下降`]},{id:`cardiology`,name:`心血管内科`,intro:`冠心病、高血压、心律失常、心力衰竭等心血管疾病诊治。`,scope:[`冠心病`,`高血压`,`心律失常`,`心力衰竭`,`心脏康复`],conditions:[`胸痛 / 胸闷`,`心悸`,`活动后气短`,`血压波动`]},{id:`neurology`,name:`神经内科`,intro:`脑血管、头痛、癫痫、认知及运动障碍等相关疾病。`,scope:[`脑血管病`,`头痛 / 眩晕`,`癫痫`,`帕金森及运动障碍`,`认知障碍`],conditions:[`头痛`,`头晕 / 眩晕`,`肢体无力 / 麻木`,`记忆力下降`]},{id:`nephrology`,name:`肾内科`,intro:`关注原发及继发性肾脏疾病、肾功能不全及透析评估。`,scope:[`肾小球疾病`,`慢性肾脏病`,`尿路感染`,`血液净化评估`],conditions:[`下肢 / 眼睑水肿`,`尿检异常`,`肾功能异常`,`高血压难以控制`]},{id:`hematology`,name:`血液内科`,intro:`贫血、出血、血栓及血液系统肿瘤相关疾病。`,scope:[`贫血`,`出凝血疾病`,`血小板异常`,`血液系统肿瘤`],conditions:[`不明原因贫血`,`瘀斑 / 出血`,`持续发热`,`血常规异常`]},{id:`rheumatology`,name:`风湿免疫科`,intro:`自身免疫性疾病、关节炎及全身性风湿病。`,scope:[`类风湿关节炎`,`脊柱关节病`,`系统性红斑狼疮`,`痛风`,`血管炎`],conditions:[`多关节痛 / 肿胀`,`晨僵`,`反复皮疹 / 口腔溃疡`,`不明原因发热`]},{id:`endocrinology`,name:`内分泌科`,intro:`糖尿病、甲状腺、垂体及肾上腺等内分泌代谢疾病。`,scope:[`糖尿病`,`甲状腺疾病`,`肥胖与代谢综合征`,`垂体 / 肾上腺疾病`],conditions:[`血糖异常`,`体重明显变化`,`怕冷 / 怕热`,`月经紊乱`]},{id:`geriatrics`,name:`老年病科`,intro:`为老年患者提供多病共存、综合评估与个体化管理。`,scope:[`老年综合评估`,`慢病管理`,`用药评估`,`衰弱与跌倒评估`],conditions:[`老年慢病控制不佳`,`多重用药`,`近期功能下降`,`跌倒 / 平衡问题`]}]},{category:`五官皮肤`,items:[{id:`ophthalmology`,name:`眼科`,intro:`负责视力、外眼及眼底相关疾病的评估与治疗。`,scope:[`白内障`,`青光眼`,`视网膜疾病`,`儿童斜弱视`],conditions:[`视力下降`,`眼痛 / 眼红`,`看东西发暗 / 变形`,`儿童视力异常`]},{id:`ent`,name:`耳鼻喉科`,intro:`耳、鼻、咽喉、头颈部常见疾病。`,scope:[`耳科`,`鼻科`,`咽喉科`,`头颈外科`],conditions:[`耳鸣 / 听力下降`,`鼻塞 / 流涕`,`咽痛 / 声音嘶哑`,`颈部肿块`]},{id:`stomatology`,name:`口腔科`,intro:`牙齿、牙周、黏膜与口腔颌面外科相关问题。`,scope:[`牙体牙髓`,`牙周`,`口腔黏膜`,`口腔颌面外科`],conditions:[`牙痛`,`牙龈出血 / 肿胀`,`口腔黏膜溃疡`,`咬合不适`]},{id:`dermatology`,name:`皮肤科`,intro:`各类皮肤、毛发及甲病。`,scope:[`过敏性疾病`,`痤疮 / 玫瑰痤疮`,`银屑病`,`皮肤肿瘤筛查`],conditions:[`皮疹 / 瘙痒`,`长期不愈皮损`,`脱发`,`可疑色素性皮损`]}]},{category:`精神心理`,items:[{id:`psychiatry`,name:`精神心理科`,intro:`情绪、焦虑、睡眠及精神心理相关问题评估与治疗。`,scope:[`抑郁 / 焦虑`,`睡眠障碍`,`躯体化障碍`,`认知与记忆问题`],conditions:[`持续情绪低落`,`过度担心 / 紧张`,`入睡困难或早醒`,`不明原因躯体不适`]}]},{category:`急诊 / 专科`,items:[{id:`emergency`,name:`急诊科`,intro:`24 小时为急症、急重症患者提供首诊评估与抢救。`,scope:[`急性胸痛`,`急性脑血管事件`,`急腹症`,`创伤 / 中毒`],conditions:[`突发剧烈胸痛`,`突发肢体无力 / 言语障碍`,`严重外伤`,`意识改变`]},{id:`pain`,name:`疼痛科`,intro:`针对慢性疼痛的综合评估与微创介入治疗。`,scope:[`颈肩腰腿痛`,`神经病理性疼痛`,`癌痛`,`头痛`],conditions:[`慢性腰痛 / 颈痛`,`带状疱疹后神经痛`,`癌性疼痛`,`反复头痛`]},{id:`rehab`,name:`康复医学科`,intro:`提供功能恢复、疼痛管理及运动相关的综合康复。`,scope:[`神经康复`,`骨科康复`,`心肺康复`,`运动损伤康复`],conditions:[`脑卒中后功能障碍`,`术后活动受限`,`慢性疼痛影响生活`,`运动损伤恢复缓慢`]},{id:`general-practice`,name:`全科医学科`,intro:`面向全人群的首诊、健康评估与慢病综合管理。`,scope:[`全科首诊`,`健康体检咨询`,`慢病管理`,`全科转诊`],conditions:[`多系统不适难以定位专科`,`慢病用药调整`,`健康咨询`,`体检异常解读`]}]}];function t(t){for(let n of e){let e=n.items.find(e=>e.id===t);if(e)return{item:e,category:n.category}}return null}export{t as n,e as t};